export function OTPFieldInvalid() {
  const form = useForm({ defaultValues: { code: "" } });
  return (
    <form.Field
      name="code"
      validators={{
        onChange: ({ value }) =>
          value.length === 6 && value !== "123456" ? "Incorrect code. Try 123456." : undefined,
        onSubmit: ({ value }) => (value.length !== 6 ? "Enter all 6 digits." : undefined),
